// #62038e מסך מסמכים קבועים של החברה — шаг 4 мастера /onboarding, роль ADMIN компании «QA Test בע"מ».
// Документы QA-AUTO-… удаляются в конце теста. Изоляция между компаниями — upload-component-profile.spec.ts.
// @data: документы компании и шаг мастера — общие для аккаунта.
import { test, expect, Page } from '@playwright/test';
import { authState, openWizardStep, qaFile, qaName, restoreWizard, todayHe, uploadItem } from '../helpers/tenderflow';

const DOCS_LABEL = 'מסמכים קבועים של החברה';

async function removeIfPresent(page: Page, fileName: string) {
  const btn = page.getByRole('button', { name: `הסרה: ${fileName}` });
  if (await btn.count()) {
    await btn.click();
    await expect(uploadItem(page, fileName)).toHaveCount(0);
  }
}

test.describe('מסך מסמכים קבועים של החברה', () => {
  test.describe.configure({ mode: 'serial' });
  test.use({ storageState: authState('admin') });
  test.afterEach(async ({ page }) => restoreWizard(page));

  // Тест «סוגי מסמכים להעלאה והנחיית פורמטים» удалён 18.11.2026: селект «סוג המסמך להעלאה» убран, тексты изменены —
  // заменён тестами company-documents-vault.spec.ts (#62038e).

  // УСТАРЕЛО 18.11.2026: тест написан под экран до TAQO (селект типа, список «קבצים מצורפים», 10MB). Сейчас загрузка идёт
  // кнопкой «העלה» в строке типа документа, файл виден внутри строки. Нужно перегенерировать по живому экрану.
  test.fixme('העלאה, צפייה, החלפה ומחיקה של מסמך קבוע נשמרים בין כניסות #62038e @desktop @data', async ({ page }) => {
    await openWizardStep(page, 4);
    const base = qaName('ocd');
    const v1 = qaFile(`${base}-v1`, 'pdf');
    const v2 = qaFile(`${base}-v2`, 'docx');

    try {
      // דרישות 2, 7–10: загрузка → в списке имя, тип, дата, метка повторного использования
      await page.getByLabel('סוג המסמך להעלאה').selectOption({ label: 'מסמך אחר' });
      await page.getByLabel(DOCS_LABEL, { exact: true }).setInputFiles(v1);
      const item1 = uploadItem(page, v1.name);
      await expect(item1.getByRole('status')).toHaveText('הועלה');
      await expect(item1).toContainText(`מסמך אחר · נוסף ב-${todayHe()} · זמין לשימוש חוזר במכרזים`);

      // AC5: сохраняется между входами
      await page.reload();
      await openWizardStep(page, 4);
      await expect(uploadItem(page, v1.name)).toBeVisible();

      // דרישה 3: просмотр — документ открывается в новой вкладке
      const [popup] = await Promise.all([
        page.waitForEvent('popup'),
        page.getByRole('button', { name: `צפייה: ${v1.name}` }).click(),
      ]);
      await expect.poll(() => popup.url()).toMatch(/^https:/);
      const viewed = await popup.context().request.get(popup.url());
      expect(viewed.status()).toBe(200);
      expect(viewed.headers()['content-type']).toContain('application/pdf');
      await popup.close();

      // דרישה 4: замена — в списке новый файл, старого нет (и после перезагрузки)
      const [chooser] = await Promise.all([
        page.waitForEvent('filechooser'),
        page.getByRole('button', { name: `החלפה: ${v1.name}` }).click(),
      ]);
      await chooser.setFiles(v2);
      await expect(uploadItem(page, v2.name).getByRole('status')).toHaveText('הועלה');
      await expect(uploadItem(page, v1.name)).toHaveCount(0);
      await page.reload();
      await openWizardStep(page, 4);
      await expect(uploadItem(page, v2.name)).toBeVisible();
      await expect(uploadItem(page, v1.name)).toHaveCount(0);

      // דרישה 5: удаление — не возвращается после перезагрузки
      await page.getByRole('button', { name: `הסרה: ${v2.name}` }).click();
      await expect(uploadItem(page, v2.name)).toHaveCount(0);
      await page.reload();
      await openWizardStep(page, 4);
      await expect(page.getByLabel('סוג המסמך להעלאה')).toBeVisible();
      await expect(page.getByText(v2.name)).toHaveCount(0);
    } finally {
      await removeIfPresent(page, v1.name);
      await removeIfPresent(page, v2.name);
    }
  });

  // УСТАРЕЛО 18.11.2026: ждёт список «קבצים מצורפים» (uploadItem) и общую зону без «מסמכים נוספים». Перегенерировать.
  test.fixme('קובץ exe וקובץ ריק נדחים עם הודעה ואינם נוספים לרשימה #62038e @desktop @data', async ({ page }) => {
    await openWizardStep(page, 4);
    const base = qaName('ocd-bad');
    const exe = qaFile(`${base}`, 'exe');
    const empty = qaFile(`${base}-empty`, 'pdf', { empty: true });
    const input = page.getByLabel(DOCS_LABEL, { exact: true });

    try {
      await input.setInputFiles(exe);
      await expect(page.getByRole('alert').filter({ hasText: `סוג הקובץ ${exe.name} אינו נתמך` })).toBeVisible();
      await expect(uploadItem(page, exe.name)).toHaveCount(0);

      await input.setInputFiles(empty);
      await expect(page.getByRole('alert').filter({ hasText: `הקובץ ${empty.name} ריק` })).toBeVisible();
      await expect(uploadItem(page, empty.name)).toHaveCount(0);
    } finally {
      await removeIfPresent(page, exe.name);
      await removeIfPresent(page, empty.name);
    }
  });
});
